const D = { energy:.6, density:.5, scale:1, speed:1, hue:96, x:.5, y:.5, tangle:.55, style:'microscopy', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.35,2.2);
const TG = cl(P.tangle,0,1), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
// slow current, incommensurate — the water is never still
const cur = .9*Math.sin(T*.31) + .5*Math.sin(T*.73+1.7) + .3*Math.sin(T*1.19);
const stir = (.3 + .9*EN)*cur + A.lowmid*.7 + K.pulse*.16*K.intensity;

// ---- the bloom/crash nutrient cycle — the piece's whole dramaturgy (~80s) -
// nutrients -> exponential bloom -> exhaustion -> starve -> sink as detritus ->
// the detritus remineralises -> nutrients return -> bloom again. Never converges.
if (S.nut == null) { S.nut = .5; S.pop = .5; }
const d0 = dt*SP;
const GR = .09*(.6 + .7*EN);                               // uptake per second
const upt = S.pop*S.nut*GR*d0;
const die = .10*S.pop*(1.15 - S.nut)*d0;
S.pop = cl(S.pop + upt*1.5*(1 - S.pop) - die, .02, 1);
S.nut = cl(S.nut - upt + die*.35 + (.05 + .012*Math.sin(T*.023))*(1 - S.nut)*d0, 0, 1);
const bloom = S.pop;                                       // 0.02 crashed .. 1 peak bloom
const health = cl(S.nut*2.4, .05, 1);                      // starving filaments go pale/yellow
const crash = 1 - health;

// ---- style ---------------------------------------------------------------
const H = P.hue;
let mode;
if (sty === 'darkfield') mode = 1; else if (sty === 'cyanotype') mode = 2;
else if (sty === 'ink_wash') mode = 3; else mode = 0;

// ---- water column ground -------------------------------------------------
const bgKey = [width,height,sd,sty,H].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(560, Math.max(220, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke();
  for (let y=0;y<bh;y++){ const v = y/bh;                   // light attenuates with depth
    if (mode === 2) g.fill(214, 84 - v*8, 34 - v*13);
    else if (mode === 3) g.fill(40, 9 + v*5, 78 - v*22);
    else if (mode === 1) g.fill(188 + v*8, 62 - v*10, 17 - v*7);
    else g.fill(H + 62 - v*10, 26 + v*12, 62 - v*24);
    g.rect(0, y, bw, 1.2); }
  for (let i=0;i<2200;i++){ g.fill(0, 0, mode===0||mode===3 ? 30 : 90, 5 + fr(i*3.9)*8);
    g.rect(fr(i*2.7)*bw, fr(i*6.3+2)*bh, 1.5, 1.5); }
  const dc = g.drawingContext;
  const rg = dc.createRadialGradient(bw*.5, bh*.06, bw*.02, bw*.5, bh*.5, bw*.95);
  rg.addColorStop(0, mode===3 ? 'rgba(255,255,255,0.22)' : 'rgba(210,255,235,0.16)');
  rg.addColorStop(1, 'rgba(0,0,0,0)'); dc.fillStyle = rg; dc.fillRect(0, 0, bw, bh);
  const vg = dc.createRadialGradient(bw*.5, bh*.5, bw*.14, bw*.5, bh*.5, bw*.84);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.38)');
  dc.fillStyle = vg; dc.fillRect(0, 0, bw, bh);
  g.pop();
}

// ---- filament pool -------------------------------------------------------
const NMAX = 40;
const reseed = (f, i) => {
  const j = i*17.3 + (f.gen = (f.gen||0)+1)*23.9;
  f.x = fr(j*1.3)*1.2 - .1; f.y = fr(j*2.7)*1.25 - .12;
  f.len = .5 + fr(j*3.1)*.55;                              // relative to its full length
  f.z = fr(j*4.3);                                          // depth plane -> blur/attenuation
  f.ph = fr(j*5.9)*6.28;
  f.wig = .55 + fr(j*6.1)*.9;
  f.chir = fr(j*7.7) < .5 ? 1 : -1;                        // chloroplast helix handedness
  f.hj = (fr(j*8.3)-.5)*26;
  f.buoy = fr(j*9.1);                                       // trapped O2 -> this one rafts up
  f.frag = 0; f.born = T;
};
if (!S.fil || S.fil.length !== NMAX || S.seedUsed !== sd) {
  S.seedUsed = sd; S.fil = [];
  for (let i=0;i<NMAX;i++){ const f = {}; reseed(f, i); f.born = T - fr(i*13.7)*40; S.fil.push(f); }
}
// filaments elongate by intercalary division while the bloom is on, fragment when it crashes
for (let i=0;i<NMAX;i++) {
  const f = S.fil[i];
  f.len = cl(f.len + dt*SP*(.028*health*(.5+.7*EN) - .05*crash*crash), .06, 1.25);
  f.y -= dt*SP*(.006 + .03*f.buoy*bloom*health);           // O2 bubbles raft the mat to the surface
  f.y += dt*SP*.05*crash*crash*(1 - f.buoy*.6);            // dead filaments sink as detritus
  if (f.len <= .07 || f.y > 1.3 || f.y < -.25) reseed(f, i);
}

// ---- draw ----------------------------------------------------------------
image(S.g, 0, 0, width, height);
const active = (4 + DN*36)*(.35 + .65*bloom);              // recruitment ramps with the bloom
const nDraw = Math.min(NMAX, Math.ceil(active));
if (mode === 1) blendMode(ADD);
strokeCap(ROUND); strokeJoin(ROUND); noFill();
const NV = 22;

for (let n=0;n<nDraw && n<NMAX;n++) {
  const f = S.fil[n];
  const av = cl(active - n, 0, 1);                          // the boundary filament fades in
  if (av <= .01) continue;
  const dep = .35 + .65*f.z;                               // near plane = big, crisp, saturated
  const L = u*.42*SC*f.len*dep;
  const bx = (f.x + (P.x-.5)*.5)*width, by = (f.y + (P.y-.5)*.5)*height;
  const ang = f.ph*.7 + Math.sin(T*.13 + f.ph)*.5 + stir*.12;
  const hh = ((P.hue + f.hj + crash*34) % 360 + 360) % 360;
  const ss = (62 - crash*40)*(.55 + .45*f.z);
  const bb = (30 + 34*f.z)*(1 - crash*.25) + crash*24;
  const wid = u*.011*SC*dep*(.6 + .5*health);
  const xs = [], ys = [];
  for (let q=0;q<=NV;q++) {
    const s = q/NV;
    // an unbranched filament, tangled by the local shear
    const tw = TG*2.4*(1 + f.wig);
    const a2 = ang + Math.sin(s*tw + f.ph + T*.21)*1.25*TG + Math.sin(s*tw*2.3 + f.ph*1.7)*.5*TG;
    const px2 = Math.cos(a2), py2 = Math.sin(a2);
    const drift = Math.sin(T*(.83 + f.wig*.4) + s*3.1 + f.ph)*u*.012*(.4 + EN)*dep
                + stir*u*.016*dep*(.3 + s*.7);
    xs.push(bx + (s - .5)*L*px2*1.0 + drift);
    ys.push(by + (s - .5)*L*py2*.9 + Math.cos(T*.67 + s*2.3 + f.ph)*u*.008*(.4+EN)*dep);
  }
  const alF = AL*av*(mode===1 ? (.24 + .5*f.z) : (.5 + .5*f.z))*(.5 + .5*health);
  // sheath
  if (mode === 2) stroke(214, 22 - f.z*14, 88 + f.z*10, 86*alF);
  else if (mode === 3) stroke(32, 12, 30 + (1-f.z)*30, 70*alF);
  else if (mode === 1) stroke(hh, ss*.9, bb + 34, 40*alF);
  else stroke(hh, ss*.5, bb + 32, 74*alF);
  strokeWeight(wid);
  beginShape(); for (let q=0;q<=NV;q++) vertex(xs[q], ys[q]); endShape();
  // helical chloroplast ribbon — the Spirogyra tell
  if (f.z > .18 || nDraw < 14) {
    if (mode === 2) stroke(214, 46, 60, 62*alF);
    else if (mode === 3) stroke(30, 18, 22, 62*alF);
    else stroke(hh, ss + 16, bb*(mode===1 ? 1.5 : .78), (mode===1?52:82)*alF);
    strokeWeight(wid*.34);
    beginShape();
    for (let q=0;q<=NV*2;q++) {
      const s = q/(NV*2), i2 = Math.min(NV, Math.round(s*NV));
      const i3 = Math.min(NV, i2+1);
      const dx = xs[i3]-xs[i2], dy = ys[i3]-ys[i2], dl = Math.max(1e-4, Math.hypot(dx,dy));
      const nx = -dy/dl, ny = dx/dl;
      const hel = Math.sin(s*38*f.chir + f.ph*2 + T*.09)*wid*.42*health;
      vertex(xs[i2] + nx*hel, ys[i2] + ny*hel);
    }
    endShape();
    // cross-walls: the cells the filament is built from
    if (f.z > .5 && nDraw < 26) {
      strokeWeight(wid*.2);
      if (mode === 2) stroke(214, 40, 52, 40*alF); else stroke(hh, ss*.5, bb*.5 + 10, 40*alF);
      for (let q=2;q<NV;q+=3) {
        const dx = xs[q+1]-xs[q], dy = ys[q+1]-ys[q], dl = Math.max(1e-4, Math.hypot(dx,dy));
        const nx = -dy/dl, ny = dx/dl;
        line(xs[q] - nx*wid*.45, ys[q] - ny*wid*.45, xs[q] + nx*wid*.45, ys[q] + ny*wid*.45);
      }
    }
  }
}
// ---- trapped oxygen: the bubbles that float the mat -----------------------
const nB = Math.round((6 + DN*26)*bloom*health);
noStroke();
for (let k=0;k<nB;k++) {
  const ph = fr(k*3.7)*6.28;
  const rise = ((T*(.035 + fr(k*5.1)*.05) + fr(k*7.3)) % 1);
  const bx = (fr(k*2.1)*1.05 - .02 + Math.sin(T*.7 + ph)*.02 + stir*.012)*width;
  const by = (1.05 - rise*1.1)*height;
  const r = u*.006*SC*(.4 + fr(k*9.7)*1.1);
  if (mode === 2) fill(214, 10, 96, 34*AL);
  else if (mode === 3) fill(34, 6, 92, 30*AL);
  else fill(H + 40, 14, 92, (mode===1?26:34)*AL);
  ellipse(bx, by, r*2, r*2*(.85 + .3*Math.sin(T*3.1 + ph)));
}
// ---- detritus rain during the crash ---------------------------------------
const nD = Math.round(30*crash*crash*(.4 + DN));
for (let k=0;k<nD;k++) {
  const ph = fr(k*11.1 + 3)*6.28;
  const fallv = ((T*.028 + fr(k*4.9)) % 1);
  const dx2 = (fr(k*6.7)*1.04 - .02 + Math.sin(T*.41 + ph)*.03 + stir*.02)*width;
  const dy2 = (fallv*1.1 - .05)*height;
  if (mode === 2) fill(216, 46, 52, 30*AL); else if (mode === 3) fill(32, 16, 40, 30*AL);
  else fill(44, 40, mode===1 ? 40 : 46, 34*AL);
  ellipse(dx2, dy2, u*.004*SC, u*.0065*SC);
}
blendMode(BLEND);
